const { app, BrowserWindow, Notification, ipcMain } = require('electron');
const path = require('path');
const { spawn } = require('child_process');

let mainWindow;
let pythonProcess;

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1200,
    height: 800,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      nodeIntegration: false,
      contextIsolation: true,
    }
  });

  // 開発環境ではViteのサーバーを、本番環境ではビルドされたHTMLを読み込む
  const isDev = !app.isPackaged;
  if (isDev) {
    mainWindow.loadURL('http://localhost:5173');
  } else {
    mainWindow.loadFile(path.join(__dirname, '../dist/index.html'));
  }
}

// ★ PC起動時の自動起動設定
app.setLoginItemSettings({
  openAtLogin: true,
  path: app.getPath('exe')
});

app.whenReady().then(() => {
  // Pythonバックエンドの起動
  startPythonBackend();

  createWindow();

  app.on('activate', function () {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

// Pythonプロセスの立ち上げ
function startPythonBackend() {
  // 開発中はpythonコマンド、本番環境(PyInstaller等でexe化後)の分岐などをここに書きます
  const scriptPath = path.join(__dirname, '../python/app.py');
  pythonProcess = spawn('python', [scriptPath]);

  pythonProcess.stdout.on('data', (data) => {
    console.log(`Python: ${data}`);
  });
}

// ★ デスクトップ通知の実行（React側から呼び出せるようにする）
ipcMain.on('show-notification', (event, { title, body }) => {
  new Notification({ title, body }).show();
});

// アプリ終了時のクリーンアップ
app.on('window-all-closed', function () {
  if (process.platform !== 'darwin') app.quit();
});

app.on('will-quit', () => {
  if (pythonProcess) {
    pythonProcess.kill();
  }
});



const { contextBridge, ipcRenderer } = require('electron');

contextBridge.exposeInMainWorld('electronAPI', {
  // React側から electronAPI.showNotification(...) として呼び出せる
  showNotification: (payload) => ipcRenderer.send('show-notification', payload)
});



