import os
import sqlite3
from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
import uvicorn

# calendar_api.py から関数をインポート
from calendar_api import add_task_to_calendar

app = FastAPI()

# Reactからのアクセスを許可
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


# データベースファイルのパス設定
BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DB_FILE = os.path.join(BASE_DIR, "tasks.db")

def init_db():
    """アプリ起動時にデータベースとテーブルを作成する"""
    conn = sqlite3.connect(DB_FILE)
    cursor = conn.cursor()
    # tasksテーブルが存在しなければ作成
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS tasks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id TEXT,
            summary TEXT NOT NULL,
            target_date TEXT NOT NULL,
            html_link TEXT,
            registered_at TEXT
        )
    ''')
    conn.commit()
    conn.close()

# サーバー起動時にデータベースを初期化
init_db()

# リクエストデータの型定義
class TaskCreate(BaseModel):
    summary: str
    date: str  # YYYY-MM-DD 形式

@app.get("/api/tasks")
def get_tasks():
    """データベースからタスクの一覧を取得するAPI"""
    conn = sqlite3.connect(DB_FILE)
    # 取得結果を辞書型(dict)として扱えるように設定
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()

    cursor.execute("SELECT * FROM tasks ORDER BY id ASC")
    rows = cursor.fetchall()
    conn.close()

    # React側が期待する形式に整形して返す
    formatted_tasks = []
    for row in rows:
        formatted_tasks.append({
            "id": row["id"],
            "event_id": row["event_id"],
            "summary": row["summary"],
            "date": row["target_date"],
            "htmlLink": row["html_link"],
            "registered_at": row["registered_at"]
        })

    return {"tasks": formatted_tasks}

