"""
calendar_api.py

Google Calendar API を使って、終日イベント（タスク）と
前日のポップアップリマインダー（12:00 / 17:00）を自動登録するスクリプト。

事前準備:
    1. Google Cloud Console で Calendar API を有効化し、
       OAuth クライアントID（デスクトップアプリ）を作成して
       credentials.json をこのファイルと同じディレクトリに置く。
    2. 必要なライブラリをインストールする（下記参照）。
    3. 本ファイルを直接実行すると、初回はブラウザで認証が求められ、
       成功すると token.json が生成され、以降はそれが再利用される。

必要なライブラリ:
    pip install google-api-python-client google-auth-httplib2 google-auth-oauthlib
"""

import os
import datetime

from google.auth.transport.requests import Request
from google.oauth2.credentials import Credentials
from google_auth_oauthlib.flow import InstalledAppFlow
from googleapiclient.discovery import build
from googleapiclient.errors import HttpError

# カレンダーの読み書きを行うためのスコープ
SCOPES = ["https://www.googleapis.com/auth/calendar"]

CREDENTIALS_FILE = "credentials.json"
TOKEN_FILE = "token.json"

# 終日イベントを登録するカレンダーのタイムゾーン（必要に応じて変更）
TIMEZONE = "Asia/Tokyo"


