def _calculate_reminder_minutes(date_str):
    """
    イベント当日（date_str, 00:00開始とみなす）に対して、
    「前日12:00」「前日17:00」がそれぞれ何分前の通知に相当するかを計算する。

    例）date_str = '2026-07-10' の場合
        イベント開始 = 2026-07-10 00:00
        前日12:00   = 2026-07-09 12:00  -> 720分前
        前日17:00   = 2026-07-09 17:00  -> 420分前
    """
    event_start = datetime.datetime.strptime(date_str, "%Y-%m-%d")
    day_before = event_start - datetime.timedelta(days=1)

    reminder_noon = day_before.replace(hour=12, minute=0, second=0, microsecond=0)
    reminder_evening = day_before.replace(hour=17, minute=0, second=0, microsecond=0)

    minutes_noon = int((event_start - reminder_noon).total_seconds() // 60)
    minutes_evening = int((event_start - reminder_evening).total_seconds() // 60)

    return minutes_noon, minutes_evening


def add_task_to_calendar(summary, date_str):
    """
    終日イベントとしてタスクをカレンダーに登録する。

    Args:
        summary (str): イベントのタイトル（タスク名）。
        date_str (str): 'YYYY-MM-DD' 形式の日付文字列。

    Returns:
        dict: 作成されたイベントのレスポンス（event id 等を含む）。
    """
    # 日付形式のバリデーション
    try:
        start_date = datetime.datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError("date_str は 'YYYY-MM-DD' 形式で指定してください。") from exc

    # 終日イベントの end は「翌日の日付」を指定するのが Google Calendar API の仕様
    end_date = start_date + datetime.timedelta(days=1)

    minutes_noon, minutes_evening = _calculate_reminder_minutes(date_str)

    event_body = {
        "summary": summary,
        "start": {
            "date": start_date.isoformat(),
            "timeZone": TIMEZONE,
        },
        "end": {
            "date": end_date.isoformat(),
            "timeZone": TIMEZONE,
        },
        "reminders": {
            "useDefault": False,
            "overrides": [
                {"method": "popup", "minutes": minutes_noon},
                {"method": "popup", "minutes": minutes_evening},
            ],
        },
    }

    service = get_calendar_service()

    try:
        created_event = (
            service.events().insert(calendarId="primary", body=event_body).execute()
        )
    except HttpError as error:
        print(f"カレンダー登録中にエラーが発生しました: {error}")
        raise

    print(f"予定を登録しました: {created_event.get('summary')}")
    print(f"  日付      : {start_date.isoformat()}")
    print(f"  リマインダー: 前日12:00（{minutes_noon}分前） / 前日17:00（{minutes_evening}分前）")
    print(f"  イベントURL : {created_event.get('htmlLink')}")

    return created_event
def get_calendar_service():
    creds = None
    if os.path.exists(TOKEN_FILE):
        creds = Credentials.from_authorized_user_file(TOKEN_FILE, SCOPES)

    if not creds or not creds.valid:
        if creds and creds.expired and creds.refresh_token:
            creds.refresh(Request())
        else:
            flow = InstalledAppFlow.from_client_secrets_file(CREDENTIALS_FILE, SCOPES)
            creds = flow.run_local_server(port=0)
        with open(TOKEN_FILE, 'w') as token:
            token.write(creds.to_json())

    return build('calendar', 'v3', credentials=creds)

def get_upcoming_events():
    try:
        service = get_calendar_service()
        # ここにカレンダー取得のロジックを書く（今回はモックデータを返します）
        # 実際には service.events().list(...).execute() 等を使用
        return [
            {"id": "1", "title": "会議", "time": "10:00"},
            {"id": "2", "title": "プログラミング", "time": "13:00"}
        ]
    except Exception as e:
        print(f"Calendar API Error: {e}")
        return []

if __name__ == "__main__":
    # 単体テスト実行用コード。
    # 他システムと切り離し、このファイル単体で動作確認するためのものです。
    # 実行すると、明日の日付で「テストタスク」という終日イベントが
    # 実際にご自身の Google カレンダー（primary）に登録されます。

    test_summary = "テストタスク"
    tomorrow = (datetime.date.today() + datetime.timedelta(days=1)).isoformat()

    print(f"テスト実行: '{test_summary}' を {tomorrow} に終日イベントとして登録します。")
    add_task_to_calendar(test_summary, tomorrow)



