  useEffect(() => {
    fetch('http://127.0.0.1:8000/api/tasks')
      .then(res => res.json())
      .then(data => setSavedTasks(data.tasks || []))
      .catch(err => console.error("履歴の取得に失敗しました:", err));
  }, []);

  // 2. 新規タスクを送信する処理
  const handleRegister = async (e) => {
    e.preventDefault();
    if (!summary || !date) return alert("タスク名と日付を入力してください");

    setLoading(true);
    try {
      const response = await fetch('http://127.0.0.1:8000/api/tasks', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ summary, date })
      });

      const result = await response.json();
      if (response.ok) {
        alert("GoogleカレンダーおよびローカルJSONに登録しました！");
        setSavedTasks([...savedTasks, result.task]); // 画面上の一覧を更新
        setSummary('');
        setDate('');
      } else {
        alert(`エラー: ${result.detail}`);
      }
    } catch (error) {
      console.error(error);
      alert("バックエンドサーバーとの通信に失敗しました。");
    } finally {
      setLoading(false);
    }
  };

  return (



