import subprocess
import sys
import os
import atexit
import time

# 起動した子プロセスを保持するリスト
processes = []

def cleanup():
    """
    プログラム終了時（エラーやCtrl+Cを含む）に呼び出され、
    バックグラウンドで動いているプロセスを安全にキルします。
    これをしないと、次回起動時に「ポート(8000)が既に使用されています」エラーになります。
    """
    print("\n[System] すべてのプロセスを終了しています...")
    for p in processes:
        if p.poll() is None: # プロセスがまだ実行中の場合
            p.terminate()
            p.wait()
    print("[System] クリーンアップ完了")

# アプリ終了時に cleanup 関数を必ず実行するように登録
atexit.register(cleanup)

def main():
    print("="*45)
    print(" 🚀 アプリケーション開発環境を起動します")
    print("="*45)

    base_dir = os.path.dirname(os.path.abspath(__file__))

    # 1. Pythonバックエンド(FastAPI)の起動
    print("[1/2] バックエンド(FastAPI)を起動中...")
    backend_path = os.path.join(base_dir, 'python', 'app.py')

    # 現在のPython環境（仮想環境など）を使ってサーバーを立ち上げる
    backend_process = subprocess.Popen([sys.executable, backend_path])
    processes.append(backend_process)

    # サーバーが立ち上がるまで少し待機
    time.sleep(2)

    # 2. フロントエンド(Vite + Electron)の起動
    print("[2/2] フロントエンド(Electron)を起動中...")

    # Windows環境とMac/Linux環境の両方で動作するように shell=True を指定
    # package.json の "dev" スクリプトを呼び出します
    frontend_process = subprocess.Popen("npm run dev", shell=True)
    processes.append(frontend_process)

    try:
        # フロントエンド（Electronのウィンドウ）が閉じられるまでここで処理をブロックして待機
        frontend_process.wait()
    except KeyboardInterrupt:
        # ターミナルで Ctrl+C が押された場合は速やかに終了処理へ
        print("\n[System] ユーザーによって中断されました。")

if __name__ == '__main__':
    main()



