    if (savedJson) {
        try {
            const parsed = JSON.parse(savedJson);
            // 【修正ポイント1】古いバージョンのデータ（配列）が残っていたらリセットして競合を防ぐ
            if (Array.isArray(parsed)) {
                allDaysData = {};
            } else {
                allDaysData = parsed;
            }
        } catch (error) {
            allDaysData = {};
        }
    }

    const today = new Date().toISOString().split('T')[0];
    const targetDateInput = document.getElementById("targetDate");
    if (targetDateInput) {
        targetDateInput.value = today;
        currentDate = today;

        targetDateInput.addEventListener("change", (e) => {
            currentDate = e.target.value;
            loadDataForDate(currentDate);
        });
    }

    // 今日のデータを読み込んで画面に反映
    loadDataForDate(today);

    const savedDesign = localStorage.getItem(DESIGN_STORAGE_KEY);
    if (savedDesign && PALETTES[savedDesign]) {
        currentDesign = savedDesign;
    }
    const designSelect = document.getElementById("graphDesignSelect");
    if (designSelect) {
        designSelect.value = currentDesign;
    }

    const directionRadios = document.querySelectorAll('input[name="graphDirection"]');
    directionRadios.forEach(radio => {
        radio.addEventListener('change', () => {
            const graphContainer = document.getElementById("graphContainer");
            if (graphContainer && graphContainer.dataset.rendered === "true") {
                checkAndGenerateGraph();
            }
        });
    });
}

function loadDataForDate(dateStr) {
    if (allDaysData[dateStr]) {
        currentItems = JSON.parse(JSON.stringify(allDaysData[dateStr]));
    } else {
        currentItems = JSON.parse(JSON.stringify(DEFAULT_ITEMS));
    }
    renderInputForms();

    // 【修正ポイント2】データを読み込んだら、自動でグラフを描画して保存させる
    checkAndGenerateGraph();
}

function saveCurrentData() {
    allDaysData[currentDate] = currentItems;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(allDaysData));
}

function moveItemUp(index) {
    if (index > 0) {
        const temp = currentItems[index - 1];
        currentItems[index - 1] = currentItems[index];
        currentItems[index] = temp;
        saveCurrentData();
        renderInputForms();
        updateGraphIfRendered();
    }
}

function moveItemDown(index) {
    if (index < currentItems.length - 1) {
        const temp = currentItems[index + 1];
        currentItems[index + 1] = currentItems[index];
        currentItems[index] = temp;
        saveCurrentData();
        renderInputForms();
        updateGraphIfRendered();
    }
}

function updateGraphIfRendered() {
    const graphContainer = document.getElementById("graphContainer");
    if (graphContainer && graphContainer.dataset.rendered === "true") {
        checkAndGenerateGraph();
    }
}

function switchView(viewName) {
    const timelineView = document.getElementById('timelineView');
    const calendarView = document.getElementById('calendarView');
    const tabs = document.querySelectorAll('.tab-btn');

    tabs.forEach(tab => tab.classList.remove('active'));

    if (viewName === 'timeline') {
        timelineView.style.display = 'block';
        calendarView.style.display = 'none';
        event.currentTarget.classList.add('active');
    } else if (viewName === 'calendar') {
        timelineView.style.display = 'none';
        calendarView.style.display = 'block';
        event.currentTarget.classList.add('active');
        fetchAndRenderCalendar();
    }
}

function onViewModeChange() {
    const mode = document.getElementById('viewModeSelect').value;
    const container = document.getElementById('dateInputContainer');
    const now = new Date();
    const currentYearMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const today = now.toISOString().split('T')[0];

    if (mode === 'day') {
        container.innerHTML = ``;
    } else if (mode === 'month') {
        container.innerHTML = ``;
    } else if (mode === 'year-month') {
        container.innerHTML = `

             〜  

        `;
    }
}

function printReport() {
    window.print();
}

function addNewItem() {
    const inputElement = document.getElementById("newItemName");
    const itemName = inputElement.value.trim();

    if (!itemName) {
        alert("項目名を入力してください。");
        return;
    }

    const isDuplicate = currentItems.some(item => item.name === itemName);
    if (isDuplicate) {
        alert("既に存在する項目名です。");
        return;
    }

    currentItems.push({ name: itemName, hours: 0 });
    saveCurrentData();
    renderInputForms();
    inputElement.value = "";
}

function updateItemHours(index, value) {
    const hours = parseFloat(value) || 0;
    currentItems[index].hours = hours;
    saveCurrentData();
}

function deleteItem(index) {
    currentItems.splice(index, 1);
    saveCurrentData();
    renderInputForms();
}

function renderInputForms() {
    const container = document.getElementById("formContainer");
    container.innerHTML = "";

    currentItems.forEach((item, index) => {
        const row = document.createElement("div");
        row.className = "form-row";

        const nameLabel = document.createElement("label");
        nameLabel.textContent = item.name;

        const nameInput = document.createElement("input");
        nameInput.type = "text";
        nameInput.value = item.name;
        nameInput.style.display = "none"; 
        nameInput.style.width = "100px"; 
        nameInput.style.marginRight = "10px";

        const hoursInput = document.createElement("input");
        hoursInput.type = "number";
        hoursInput.value = item.hours;
        hoursInput.min = "0";
        hoursInput.max = "24";
        hoursInput.step = "0.5";
        hoursInput.oninput = (e) => {
            updateItemHours(index, e.target.value);
            updateGraphIfRendered();
        };

        const upBtn = document.createElement("button");
        upBtn.textContent = "↑";
        upBtn.className = "btn-move";
        upBtn.disabled = index === 0;
        upBtn.onclick = () => moveItemUp(index);

        const downBtn = document.createElement("button");
        downBtn.textContent = "↓";
        downBtn.className = "btn-move";
        downBtn.disabled = index === currentItems.length - 1;
        downBtn.onclick = () => moveItemDown(index);

        const renameBtn = document.createElement("button");
        renameBtn.textContent = "名前変更";
        renameBtn.className = "btn-rename";

        let isEditing = false;
        renameBtn.onclick = () => {
            const errorElement = document.getElementById("errorMessage");

            if (!isEditing) {
                isEditing = true;
                nameLabel.style.display = "none";        
                nameInput.style.display = "inline-block";
                renameBtn.textContent = "確定";           
                nameInput.focus();
            } else {
                const newName = nameInput.value.trim();

                if (newName === "") {
                    errorElement.textContent = "項目名を空にはできません。";
                    nameInput.value = item.name; 
                } else {
                    const isDuplicate = currentItems.some((x, i) => i !== index && x.name === newName);
                    if (isDuplicate) {
                        errorElement.textContent = "既に存在する項目名です。";
                        nameInput.value = item.name; 
                    } else {
                        currentItems[index].name = newName;
                        errorElement.textContent = ""; 
                        saveCurrentData();
                        updateGraphIfRendered();
                    }
                }

                isEditing = false;
                nameLabel.textContent = currentItems[index].name; 
                nameLabel.style.display = "inline-block";
                nameInput.style.display = "none";
                renameBtn.textContent = "名前変更";
            }
        };

        const deleteBtn = document.createElement("button");
        deleteBtn.textContent = "削除";
        deleteBtn.className = "btn-delete";
        deleteBtn.onclick = () => deleteItem(index);

        row.appendChild(nameLabel);
        row.appendChild(nameInput);
        row.appendChild(hoursInput);
        row.appendChild(upBtn);
        row.appendChild(downBtn);
        row.appendChild(renameBtn);
        row.appendChild(deleteBtn);

        container.appendChild(row);
    });
}

function onDesignChange() {
    const designSelect = document.getElementById("graphDesignSelect");
    currentDesign = designSelect.value;
    localStorage.setItem(DESIGN_STORAGE_KEY, currentDesign);

    const graphContainer = document.getElementById("graphContainer");
    if (graphContainer && graphContainer.dataset.rendered === "true") {
        checkAndGenerateGraph();
    }
}

function checkAndGenerateGraph() {
    const errorElement = document.getElementById("errorMessage");
    if(errorElement) errorElement.textContent = "";

    const totalHours = currentItems.reduce((sum, item) => sum + item.hours, 0);

    if (totalHours > 24) {
        const overHours = totalHours - 24;
        if(errorElement) errorElement.textContent = `各項目を足して24になるよう調整してください（${overHours}時間over）`;
        document.getElementById("graphContainer").innerHTML = "";
        document.getElementById("graphContainer").dataset.rendered = "false";
        return;
    }

    const targetItems = currentItems.filter(item => item.hours > 0);
    const direction = document.querySelector('input[name="graphDirection"]:checked').value;

    // 生成と同時にデータもセーブしておく
    saveCurrentData();
    renderGraph(targetItems, direction);
}

function renderGraph(items, direction) {
    const graphContainer = document.getElementById("graphContainer");
    graphContainer.innerHTML = "";
    graphContainer.dataset.rendered = "true";

    if (items.length === 0) {
        graphContainer.innerHTML = "
表示する項目がありません。時間を入力してください。";
        return;
    }

    const palette = PALETTES[currentDesign] || PALETTES["pattern-a"];
    const graph = document.createElement("div");
    graph.className = `timeline-graph ${currentDesign} ${direction}`;

    const scale = document.createElement("div");
    scale.className = "timeline-scale";
    [0, 6, 12, 18, 24].forEach(hour => {
        const tick = document.createElement("span");
        tick.textContent = `${hour}h`;
        scale.appendChild(tick);
    });
    graph.appendChild(scale);

    const track = document.createElement("div");
    track.className = "timeline-track";
    graph.appendChild(track);

    const legend = document.createElement("ul");
    legend.className = "timeline-legend";

    items.forEach((item, index) => {
        const color = palette[index % palette.length];

        const segment = document.createElement("div");
        segment.className = "timeline-segment";
        segment.style.background = color;

        if (direction === 'vertical') {
            segment.style.height = "0%";
            segment.style.width = "100%";
        } else {
            segment.style.width = "0%";
            segment.style.height = "100%";
        }

        segment.title = `${item.name}: ${item.hours}時間`;

        // 縦横で文字の表示方向を調整するためのスパン
        const textSpan = document.createElement("span");
        textSpan.className = "segment-text";
        textSpan.textContent = `${item.name} ${item.hours}h`;
        segment.appendChild(textSpan);

        track.appendChild(segment);

        const legendItem = document.createElement("li");
        const dot = document.createElement("span");
        dot.className = "legend-dot";
        dot.style.background = color;
        legendItem.appendChild(dot);
        legendItem.appendChild(document.createTextNode(`${item.name}（${item.hours}h）`));
        legend.appendChild(legendItem);

        const targetRatio = (item.hours / 24) * 100;

        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                if (direction === 'vertical') {
                    segment.style.height = `${targetRatio}%`;
                } else {
                    segment.style.width = `${targetRatio}%`;
                }
            });
        });
    });

    graph.appendChild(legend);
    graphContainer.appendChild(graph);
}

function getWeekDays(baseDateStr) {
    const date = new Date(baseDateStr);
    const day = date.getDay(); 
    const diffToMonday = day === 0 ? -6 : 1 - day;

    const monday = new Date(date);
    monday.setDate(date.getDate() + diffToMonday);

    const weekDates = [];
    for (let i = 0; i < 7; i++) {
        const d = new Date(monday);
        d.setDate(monday.getDate() + i);
        weekDates.push(d.toISOString().split('T')[0]);
    }
    return weekDates; 
}

function renderWeeklyTimelines(container, weekDates) {
    const wrapper = document.createElement("div");
    wrapper.className = "weekly-report-wrapper";

    const weekTitle = document.createElement("h3");
    weekTitle.textContent = `📊 週間レポート (${weekDates[0]} 〜 ${weekDates[6]})`;
    weekTitle.style.width = "100%"; // タイトルは全幅
    wrapper.appendChild(weekTitle);

    const daysOfWeek = ["月", "火", "水", "木", "金", "土", "日"];
    const direction = document.querySelector('input[name="graphDirection"]:checked').value;

    // 【カレンダー表示用】コンテナ自身にも縦横のクラスを付けてCSSでレイアウトしやすくする
    wrapper.classList.add(`layout-${direction}`);

    weekDates.forEach((dateStr, index) => {
        const dayData = allDaysData[dateStr] || []; 

        const daySection = document.createElement("div");
        daySection.className = "weekly-day-section";

        const dateHeader = document.createElement("h4");
        dateHeader.textContent = `${dateStr} (${daysOfWeek[index]})`;
        dateHeader.style.margin = "5px 0";
        daySection.appendChild(dateHeader);

        const tempGraphContainer = document.createElement("div");
        tempGraphContainer.id = `weekly-graph-${dateStr}`;
        daySection.appendChild(tempGraphContainer);
        wrapper.appendChild(daySection);

        if (dayData.length === 0) {
            tempGraphContainer.innerHTML = "
記録がありません";
        } else {
            const totalHours = dayData.reduce((sum, item) => sum + item.hours, 0);
            if (totalHours > 24) {
                tempGraphContainer.innerHTML = "
※24h over";
            } else {
                const validItems = dayData.filter(item => item.hours > 0);
                generateSingleGraphHtml(tempGraphContainer, validItems, direction);
            }
        }
    });

    container.appendChild(wrapper);
}

function generateSingleGraphHtml(targetElement, items, direction) {
    const palette = PALETTES[currentDesign] || PALETTES["pattern-a"];
    const graph = document.createElement("div");
    graph.className = `timeline-graph ${currentDesign} ${direction}`;
    graph.style.marginTop = "10px";

    const scale = document.createElement("div");
    scale.className = "timeline-scale";
    [0, 6, 12, 18, 24].forEach(hour => {
        const tick = document.createElement("span");
        tick.textContent = `${hour}h`;
        scale.appendChild(tick);
    });
    graph.appendChild(scale);

    const track = document.createElement("div");
    track.className = "timeline-track";
    graph.appendChild(track);

    const legend = document.createElement("ul");
    legend.className = "timeline-legend";

    items.forEach((item, index) => {
        const color = palette[index % palette.length];
        const segment = document.createElement("div");
        segment.className = "timeline-segment";
        segment.style.background = color;

        if (direction === 'vertical') {
            segment.style.height = `${(item.hours / 24) * 100}%`;
            segment.style.width = "100%";
        } else {
            segment.style.width = `${(item.hours / 24) * 100}%`;
            segment.style.height = "100%";
        }

        const textSpan = document.createElement("span");
        textSpan.className = "segment-text";
        textSpan.textContent = `${item.name} ${item.hours}h`;
        segment.appendChild(textSpan);

        track.appendChild(segment);

        const legendItem = document.createElement("li");
        const dot = document.createElement("span");
        dot.className = "legend-dot";
        dot.style.background = color;
        legendItem.appendChild(dot);
        legendItem.appendChild(document.createTextNode(`${item.name}（${item.hours}h）`));
        legend.appendChild(legendItem);
    });

    graph.appendChild(legend);
    targetElement.appendChild(graph);
}

async function fetchAndRenderCalendar() {
    const calendarContainer = document.getElementById("calendarContainer");
    calendarContainer.innerHTML = "
データを読み込み中...";

    const baseDate = document.getElementById("targetDate").value;
    const weekDates = getWeekDays(baseDate);

    calendarContainer.innerHTML = ""; 

    renderWeeklyTimelines(calendarContainer, weekDates);

    try {
        const [tasksResponse, eventsResponse] = await Promise.all([
            fetch(`${BACKEND_URL}/api/tasks`).then(res => res.json()).catch(() => ({ tasks: [] })),
            fetch(`${BACKEND_URL}/api/events`).then(res => res.json()).catch(() => ({ events: [] }))
        ]);

        const tasks = tasksResponse.tasks || [];
        const events = eventsResponse.events || [];

        const listWrapper = document.createElement("div");
        listWrapper.className = "calendar-list-wrapper";
        // 略：APIからのタスク表示（既存のロジック）
        // calendarContainer.appendChild(listWrapper);

    } catch (error) {
        console.error("API取得エラー:", error);
    }
}

